import sys


def feasible(P, Q, T):
    """Whether the target is reachable in T operations."""
    k, m = len(P), len(Q)
    if m > k:
        return False
    if abs(P[0] - Q[0]) > T or abs(P[-1] - Q[-1]) > T:
        return False

    parity = T & 1
    lp = rp = 0

    # Possible cuts after the previous target group form an interval
    # [a, b], filtered by the cut-validity condition.
    a = b = -1

    for s, q in enumerate(Q):
        low = q - T
        high = q + T

        while lp < k and P[lp] < low:
            lp += 1
        while rp < k and P[rp] <= high:
            rp += 1

        L = lp
        R = rp - 1
        if L > R:
            return False

        if s == 0:
            start = 0
        else:
            x = max(a, L - 1)
            r = x
            previous_q = Q[s - 1]

            while r <= b:
                d_left = previous_q - P[r]
                d_right = q - P[r + 1]

                if d_left > d_right:
                    break
                if d_left == d_right and (d_left & 1) == parity:
                    break
                r += 1

            if r > b:
                return False
            start = r + 1

        if start < L or start > R:
            return False

        if s == m - 1:
            return R == k - 1

        a = start
        b = min(R, k - 2)
        if a > b:
            return False

    return False


def solve_case(n, A, B):
    if A == B:
        return 0

    P = [i + 1 for i, c in enumerate(A) if c == 49]
    Q = [i + 1 for i, c in enumerate(B) if c == 49]
    k, m = len(P), len(Q)

    if k < m:
        return -1

    if m == 1:
        q = Q[0]
        return max(abs(P[0] - q), abs(P[-1] - q))

    if k == m:
        D = [q - p for p, q in zip(P, Q)]
        M = max(abs(x) for x in D)

        for i in range(k - 1):
            if D[i] < D[i + 1]:
                return -1

        parity_mask = 0
        i = 0
        while i < k:
            j = i + 1
            while j < k and D[j] == D[i]:
                j += 1
            if j - i >= 2:
                parity_mask |= 1 << (D[i] & 1)
            i = j

        if parity_mask == 3:
            return -1
        if parity_mask == 0:
            return M

        required_parity = 0 if parity_mask == 1 else 1
        if (M & 1) != required_parity:
            M += 1
        return M

    lower_bound = max(abs(P[0] - Q[0]), abs(P[-1] - Q[-1]))
    INF = 10 ** 9

    def search_parity(parity, upper):
        lo = lower_bound + ((parity - (lower_bound & 1)) & 1)
        hi = upper
        if hi >= 0 and (hi & 1) != parity:
            hi -= 1

        if hi < lo or hi < 0:
            return INF
        if lo == hi:
            return lo if feasible(P, Q, lo) else INF

        if feasible(P, Q, lo):
            return lo
        if not feasible(P, Q, hi):
            return INF

        # lo is infeasible and hi is feasible. Values increase by two.
        lo_index = (lo - parity) // 2
        hi_index = (hi - parity) // 2

        while hi_index - lo_index > 1:
            mid = (lo_index + hi_index) // 2
            value = 2 * mid + parity
            if feasible(P, Q, value):
                hi_index = mid
            else:
                lo_index = mid

        return 2 * hi_index + parity

    best = INF
    first_parity = lower_bound & 1

    for parity in (first_parity, 1 - first_parity):
        upper = n if best == INF else min(n, best - 1)
        candidate = search_parity(parity, upper)
        if candidate < best:
            best = candidate
        if best == lower_bound:
            break

    return -1 if best == INF else best


def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    answers = []

    for _ in range(t):
        n = int(data[pos])
        A = data[pos + 1]
        B = data[pos + 2]
        pos += 3
        answers.append(str(solve_case(n, A, B)))

    sys.stdout.write("\n".join(answers) + "\n")


if __name__ == "__main__":
    main()
